mapper.insert:
insert into cmr9900
(CR_ACPTNO,CR_SEQNO,CR_LOCAT,CR_CONFNAME,CR_TEAM,CR_TEAMCD,CR_STATUS,CR_CONGBN,
CR_COMMON, CR_BLANK,CR_EMGER,CR_HOLI,CR_SGNGBN,CR_ORGSTEP,CR_BASEUSR, CR_PRCSW)
(SELECT #{CM_ACPTNO},1,lpad(a.CM_seqno,2,'0'),a.CM_NAME,a.CM_JOBCD,a.CM_GUBUN,
'0',a.CM_COMMON,a.CM_COMMON,a.CM_BLANK,a.CM_EMG,a.CM_HOLIDAY,
a.CM_POSITION,a.CM_ORGSTEP,a.CM_JOBCD,a.CM_PRCSW
FROM Cmm0060 a,cmm0040 b
WHERE a.CM_SYSCD=#{CM_SYSCD}
AND a.CM_REQCD= #{CM_QRYCD} 
and b.cm_userid= #{CM_USERID}

	and CM_GUBUN=#{CM_GUBUN}

AND a.CM_MANID=decode(b.cm_manid,'N','2','1')	)

mapper.update:
update cmr9900
set CR_TEAM=


 		#{CR_TEAM}


		CR_SGNGBN



	,CR_BASEUSR = #{CR_BASEUSR}

WHERE CR_ACPTNO = #{CR_ACPTNO}
AND CR_TEAMCD=#{CR_TEAMCD}
